# inviters.py
# ------------------------------------------------------------
# "מזמין" (the person who invited a visitor) as a managed list instead of free text.
#
# The value still lives where it always did: in the visitor's `properties` JSON, under
# the key the data already uses (default "מזמין"; the key name can be changed in the
# settings, and a few common spellings are recognised too). Nothing about the visitors
# changes just because this module exists. On top of that:
#   * a list of inviters (table `inviters`), managed by an admin;
#   * an admin switch "an inviter is required" (like the information-security switch):
#     when on, saving a visitor needs an inviter chosen from the list, and the stored
#     text is the list's spelling;
#   * a migration from the existing free text: a preview groups the values that differ
#     only in spaces / letter case, "add to the list" is non-destructive, and
#     "unify spelling" rewrites those visitors' value to the list's spelling (backup first);
#   * reports and statistics group by the inviter, matching the free text to the list
#     ignoring spaces and letter case, so they are right even before any rewrite.
#
#   GET    /inviters                          list + switch + key   (visitor/report viewers)
#   POST   /inviters                          add                   (admin.settings)
#   PUT    /inviters/{id}                     rename / (de)activate (admin.settings)
#   DELETE /inviters/{id}                     remove from the list  (admin.settings)
#   PUT    /inviters/config                   switch + key name     (admin.settings)
#   GET    /inviters/migration/preview        what the data holds   (admin.settings)
#   POST   /inviters/migration/apply          add to list / unify   (admin.settings)
# ------------------------------------------------------------

import re
from collections import Counter
from datetime import datetime
from typing import Dict, List, Optional

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel
from sqlalchemy import Boolean, Column, DateTime, Integer, String
from sqlalchemy.orm import Session

from . import database, models, settings_store
from .dedupe import backup_database
from .dependencies import require_any_permission, require_permission
from .routes_locations import FeatureFlag, _flag, _set_flag
from .visitor_extras import find_key

FLAG_REQUIRE_INVITER = "visitors.require_inviter"
KEY_INVITER_KEY = "visitors.inviter_key"
DEFAULT_KEY = "מזמין"
KNOWN_ALIASES = (
    "מזמין",
    "המזמין",
    "שם המזמין",
    "שם מזמין",
    "גורם מזמין",
    "מארח",
    "inviter",
    "host",
)
NO_INVITER = "ללא מזמין"
MAX_NAME = 200


class Inviter(models.Base):
    __tablename__ = "inviters"
    id = Column(Integer, primary_key=True, index=True)
    name = Column(String(MAX_NAME), nullable=False, unique=True)
    active = Column(Boolean, nullable=False, default=True)
    created_at = Column(DateTime, default=datetime.now)


# ---- helpers --------------------------------------------------------------------


def norm(text) -> str:
    """Spaces collapsed, letter case ignored: 'דני  כהן ' and 'דני כהן' are the same inviter."""
    return re.sub(r"\s+", " ", str(text or "")).strip().casefold()


def clean(text) -> str:
    return re.sub(r"\s+", " ", str(text or "")).strip()


def configured_key(db: Session) -> str:
    row = db.query(FeatureFlag).filter(FeatureFlag.key == KEY_INVITER_KEY).first()
    return (row.value or "").strip() if row and (row.value or "").strip() else DEFAULT_KEY


def alias_list(db: Session) -> tuple:
    key = configured_key(db)
    return (key,) + tuple(a for a in KNOWN_ALIASES if a != key)


def raw_value(properties, aliases, exact: bool = False) -> Optional[str]:
    """The inviter text of a visitor (first alias that holds a value), or None.
    exact=True gives it exactly as stored (stray spaces included); else spaces are tidied."""
    props = properties or {}
    for alias in aliases:
        key = find_key(props, [alias])
        if key is not None:
            text = clean(props[key])
            if text:
                return str(props[key]) if exact else text
    return None


class Context:
    """Everything needed to name the inviter of a visitor (built once per request)."""

    def __init__(self, db: Session):
        self.aliases = alias_list(db)
        self.items = db.query(Inviter).order_by(Inviter.name).all()
        self.by_norm = {norm(i.name): i for i in self.items}

    def of(self, properties) -> str:
        """The inviter of a visitor as the list spells it (else as typed); NO_INVITER if none."""
        text = raw_value(properties, self.aliases)
        if text is None:
            return NO_INVITER
        hit = self.by_norm.get(norm(text))
        return hit.name if hit else text


def visitor_ids_of_inviter(db: Session, inviter: Optional[str]) -> Optional[set]:
    """dbids of the visitors invited by `inviter` (None = no filter)."""
    if not inviter:
        return None
    ctx = Context(db)
    want = clean(inviter)
    hit = ctx.by_norm.get(norm(want))
    want = hit.name if hit else want
    return {
        dbid
        for dbid, props in db.query(models.Visitor.dbid, models.Visitor.properties).all()
        if ctx.of(props or {}) == want or norm(ctx.of(props or {})) == norm(want)
    }


def check_inviter(db: Session, properties):
    """When the switch is on: an inviter from the list is required. Returns the properties to
    store (the inviter in the list's spelling) or raises ValueError with an operator message."""
    if not _flag(db, FLAG_REQUIRE_INVITER):
        return properties
    ctx = Context(db)
    props = dict(properties or {})
    text = raw_value(props, ctx.aliases)
    if text is None:
        raise ValueError("מזמין הוא שדה חובה. יש לבחור מהרשימה")
    hit = ctx.by_norm.get(norm(text))
    if hit is None or not hit.active:
        raise ValueError(
            "המזמין '{}' לא קיים ברשימה. יש לבחור מהרשימה, או שמנהל יוסיף אותו".format(text)
        )
    key = None
    for alias in ctx.aliases:
        key = find_key(props, [alias])
        if key is not None and clean(props[key]):
            break
        key = None
    props[key or ctx.aliases[0]] = hit.name
    return props


