def _rewrite(db: Session, aliases: tuple, mapping: Dict[str, str]) -> int:
    """Set the inviter text of every visitor whose normalized text is in `mapping` to the
    mapped spelling (only where it differs). Returns how many visitors changed."""
    changed = 0
    for v in db.query(models.Visitor).all():
        props = v.properties or {}
        for alias in aliases:
            key = find_key(props, [alias])
            if key is None:
                continue
            text = clean(props[key])
            if not text:
                continue
            target = mapping.get(norm(text))
            if target is not None and props[key] != target:
                new = dict(props)
                new[key] = target
                v.properties = new
                changed += 1
            break
    return changed


