    db: Session = Depends(database.get_db),
):
    info = _groups(db)
    to_add = [g["canonical"] for g in info["groups"] if not g["in_list"]]
    mapping = {norm(g["canonical"]): g["canonical"] for g in info["groups"]}
    needs = [g for g in info["groups"] if g["needs_unify"]]
    backup = None
    if body.rewrite and needs:
        backup = backup_database("inviters")  # raises (nothing changes) if the copy fails
    for name in to_add:
        db.add(Inviter(name=name, active=True))
    db.flush()
    rewritten = _rewrite(db, alias_list(db), mapping) if body.rewrite else 0
    db.commit()
    settings_store.audit(
        db,
        user,
        "inviter.migration",
        "added {}, rewritten {} visitors, backup {}".format(len(to_add), rewritten, backup),
    )
    return {"added": len(to_add), "rewritten": rewritten, "backup": backup}

